     3→export default class Player extends Phaser.Physics.Arcade.Sprite {
     4→  private cursors!: Phaser.Types.Input.Keyboard.CursorKeys;
     5→  private speed: number;
     6→  private baseSpeed: number; // 기본 속도 저장
     7→  private texturePrefix: string;
     8→  private leftKeyDown: boolean = false;
     9→  private rightKeyDown: boolean = false;
    10→  private readonly onKeyDown: (e: KeyboardEvent) => void;
    11→  private readonly onKeyUp: (e: KeyboardEvent) => void;
    12→
    13→  // 아이템 효과 상태
    14→  private isInvincible: boolean = false;
    15→  private speedBoostActive: boolean = false;
    16→
    17→  // 효과 타이머
    18→  private invincibleTimer?: Phaser.Time.TimerEvent;
    19→  private speedBoostTimer?: Phaser.Time.TimerEvent;
    20→  private rainbowTimer?: Phaser.Time.TimerEvent;
    21→
    22→  constructor(scene: Phaser.Scene, x: number, y: number, speed: number = 300, texturePrefix: string = '') {
    23→    // 기본 텍스처는 front (정면)
    24→    super(scene, x, y, `${texturePrefix}front`);
    25→    this.speed = speed;
    26→    this.baseSpeed = speed; // 기본 속도 저장
    27→    this.texturePrefix = texturePrefix;
    28→
    29→    // 씬에 추가
    30→    scene.add.existing(this);
    31→    scene.physics.add.existing(this);
    32→
    33→    // 캐릭터 크기 설정
    34→    this.setDisplaySize(50, 80);
    35→
    36→    // 히트박스: 텍스처 해상도와 무관하게 world pixel 크기 고정
    37→    // setSize/setOffset 은 frame pixel 단위이므로 scaleX/Y 로 역산
    38→    // 목표 world 크기: 20×40 px (display 50×80 의 40%/50%), 중앙 정렬
    39→    const sx = this.scaleX;  // = 50 / textureWidth
    40→    const sy = this.scaleY;  // = 80 / textureHeight
    41→    this.setSize(20 / sx, 40 / sy);
    42→    this.setOffset((50 - 20) / 2 / sx, (80 - 40) / 2 / sy);
    43→
    44→    // 물리 설정
    45→    this.setCollideWorldBounds(true);
    46→    this.setImmovable(true);
    47→
    48→    // Phaser 키보드 입력
    49→    this.cursors = scene.input.keyboard!.createCursorKeys();
    50→
    51→    // window 레벨 키보드 이벤트 (canvas 포커스와 무관하게 동작)
    52→    this.onKeyDown = (e: KeyboardEvent) => {
    53→      if (e.key === 'ArrowLeft') this.leftKeyDown = true;
    54→      if (e.key === 'ArrowRight') this.rightKeyDown = true;
    55→    };
    56→    this.onKeyUp = (e: KeyboardEvent) => {
    57→      if (e.key === 'ArrowLeft') this.leftKeyDown = false;
    58→      if (e.key === 'ArrowRight') this.rightKeyDown = false;
    59→    };
    60→    // capture: true → window capture phase는 이벤트 전파 최우선 단계
    61→    // Vercel Preview 툴바 등 외부 스크립트가 ArrowLeft/Right를 가로채도 우선 실행됨
    62→    window.addEventListener('keydown', this.onKeyDown, { capture: true });
    63→    window.addEventListener('keyup', this.onKeyUp, { capture: true });
    64→
    65→    // shutdown은 restart/stop/destroy 시 항상 먼저 호출됨 → 한 번만 등록으로 충분
    66→    scene.events.once('shutdown', this.removeKeyListeners, this);
    67→  }
    68→
    69→  private removeKeyListeners() {
    70→    window.removeEventListener('keydown', this.onKeyDown, { capture: true });
    71→    window.removeEventListener('keyup', this.onKeyUp, { capture: true });
    72→  }
    73→
    74→  update() {
    75→    let isMoving = false;
    76→
    77→    // 좌우 이동 (Phaser 키보드 OR window 레벨 키보드 둘 다 체크)
    78→    if (this.cursors.left.isDown || this.leftKeyDown) {
    79→      this.setVelocityX(-this.speed);
    80→      this.setTexture(`${this.texturePrefix}left`);
    81→      isMoving = true;
    82→    } else if (this.cursors.right.isDown || this.rightKeyDown) {
    83→      this.setVelocityX(this.speed);
    84→      this.setTexture(`${this.texturePrefix}right`);
    85→      isMoving = true;
    86→    } else {
    87→      this.setVelocityX(0);
    88→    }
    89→
    90→    // 터치/마우스 입력 처리 (화면 중앙 기준)
    91→    if (this.scene.input.activePointer.isDown) {
    92→      const pointerX = this.scene.input.activePointer.x;
    93→      const screenCenter = this.scene.cameras.main.width / 2;
    94→
    95→      if (pointerX < screenCenter) {
    96→        this.setVelocityX(-this.speed);
    97→        this.setTexture(`${this.texturePrefix}left`); // 왼쪽 이미지
    98→        isMoving = true;
    99→      } else if (pointerX > screenCenter) {
   100→        this.setVelocityX(this.speed);
   101→        this.setTexture(`${this.texturePrefix}right`); // 오른쪽 이미지
   102→        isMoving = true;
   103→      }
   104→    }
   105→
   106→    // 멈춰있을 때는 정면 이미지
   107→    if (!isMoving && this.body?.velocity.x === 0) {
   108→      this.setTexture(`${this.texturePrefix}front`);
   109→    }
   110→  }
   111→
   112→  // 헤르메스 신발 효과: 10초간 속도 2배 증가
   113→  activateSpeedBoost(duration: number = 10000) {
   114→    // 기존 타이머가 있으면 제거
   115→    if (this.speedBoostTimer) {
   116→      this.speedBoostTimer.remove();
   117→    }
   118→
   119→    // 속도 증가 (2배)
   120→    this.speedBoostActive = true;
   121→    this.speed = this.baseSpeed * 2;
   122→
   123→    // 시각적 피드백: 노란색 틴트
   124→    this.setTint(0xffff00);
   125→
   126→    // 일정 시간 후 원래 속도로 복구
   127→    this.speedBoostTimer = this.scene.time.addEvent({
   128→      delay: duration,
   129→      callback: () => {
   130→        this.speedBoostActive = false;
   131→        this.speed = this.baseSpeed;
   132→        // 무적이 아니면 틴트 제거
   133→        if (!this.isInvincible) {
   134→          this.clearTint();
   135→        } else {
   136→          // 무적 효과만 남김
   137→          this.setTint(0x00ffff);
   138→        }
   139→      },
   140→      callbackScope: this
   141→    });
   142→  }
   143→
   144→  // 무지개 별 효과: 5초간 무적
   145→  activateInvincibility(duration: number = 5000) {
   146→    // 기존 타이머가 있으면 제거
   147→    if (this.invincibleTimer) {
   148→      this.invincibleTimer.remove();
   149→    }
   150→    if (this.rainbowTimer) {
   151→      this.rainbowTimer.remove();
   152→    }
   153→
   154→    // 무적 활성화
   155→    this.isInvincible = true;
   156→
   157→    // 무지개 색상 배열 (빨주노초파남보)
   158→    const rainbowColors = [
   159→      0xff0000, // 빨강
   160→      0xff7700, // 주황
   161→      0xffff00, // 노랑
   162→      0x00ff00, // 초록
   163→      0x00ffff, // 하늘
   164→      0x0000ff, // 파랑
   165→      0xff00ff  // 보라
   166→    ];
   167→
   168→    let colorIndex = 0;
   169→
   170→    // 무지개 색상 순환 효과 (150ms마다 색상 변경)
   171→    this.rainbowTimer = this.scene.time.addEvent({
   172→      delay: 150,
   173→      callback: () => {
   174→        this.setTint(rainbowColors[colorIndex]);
   175→        colorIndex = (colorIndex + 1) % rainbowColors.length;
   176→      },
   177→      callbackScope: this,
   178→      loop: true
   179→    });
