   633→
   634→    // 한 번 더 / 메인으로 버튼
   635→    const againBtn = this.add.rectangle(200, 445, 260, 52, 0x080818)
   636→      .setStrokeStyle(1, 0x00ff41).setInteractive({ useHandCursor: true });
   637→    this.add.text(200, 445, '한 번 더', {
