   267→      }).setOrigin(0.5);
   268→      this.time.delayedCall(2200, () => { if (errMsg.active) errMsg.destroy(); });
   269→      return;
   270→    }
   271→
   272→    this.clearUI();
   273→
   274→    const count = type === 'multi' ? 10 : 1;
   275→
   276→    try {
   277→      // ① 영상(6초) + API 호출 병렬 실행 — 영상 보는 동안 응답 대기
   278→      const [result] = await Promise.all([
