import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import { GLITCH_PARAMS } from '../config/abilityParams';

/**
 * 글리치 (SR) — 분신 소환
 * ★0: 200점마다 1개  / ★1: 180점마다 1개
 * ★2: 160점마다 2개  / ★3: 140점마다 2개 + 분신 소멸 시 주변 일반 똥 2개 파괴
 */
export class GlitchAbility extends BaseAbility {
  private ghost?: Phaser.Physics.Arcade.Sprite;
  private posHistory: Array<{ x: number; y: number }> = [];
  private readonly TRAIL_FRAMES = 12; // ~0.2초 딜레이 (60fps 기준)
  // timer + ghost 쌍으로 추적: 완료 시 배열에서 제거, onDestroy 시 ghost도 함께 정리
  private pendingAttacks: Array<{ timer: Phaser.Time.TimerEvent; ghost: Phaser.GameObjects.Image }> = [];


  override onCreate(api: GameSceneAPI): void {
    // 초기 위치는 플레이어와 동일하게 (히스토리가 쌓이면서 자연스럽게 딜레이 생김)
    this.ghost = api.scene.physics.add.sprite(api.player.x, api.player.y, 'glitch_front');
    this.ghost.setDisplaySize(60, 80).setAlpha(0.45).setDepth(5);

    // 중력 비활성화
    const body = this.ghost.body as Phaser.Physics.Arcade.Body;
    body.setAllowGravity(false);

    // 일반 똥은 통과 (overlap 없음)
    // 특수 똥은 분신이 닿으면 전체 수집 처리 (카운트++, 점수, 획득 텍스트)
    const makeCollect = (
      collectFn: (p: Phaser.Physics.Arcade.Sprite) => void,
    ): Phaser.Types.Physics.Arcade.ArcadePhysicsCallback =>
      (_, p) => {
        const sp = p as Phaser.Physics.Arcade.Sprite;
        if (!sp.active) return;
        collectFn(sp);
      };
    api.scene.physics.add.overlap(this.ghost, api.goldPoops,    makeCollect(p => api.collectGoldPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.diamondPoops, makeCollect(p => api.collectDiamondPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.topazPoops,   makeCollect(p => api.collectTopazPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.rainbowPoops, makeCollect(p => api.collectRainbowPoop(p)));
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % GLITCH_PARAMS.collectInterval === 0) {
      this.collectSpecialWithGhost(api, GLITCH_PARAMS.collectCount);
    }
  }

  override onUpdate(api: GameSceneAPI): void {
    if (!this.ghost) return;
    // 현재 플레이어 위치를 히스토리에 기록
    this.posHistory.push({ x: api.player.x, y: api.player.y });
    if (this.posHistory.length > this.TRAIL_FRAMES) {
      // TRAIL_FRAMES 이전의 위치로 이동 → 약 0.2초 지연 잔상 효과
      const target = this.posHistory.shift()!;
      this.ghost.x = target.x;
      this.ghost.y = target.y;
    } else {
      // 히스토리가 쌓이기 전까지는 플레이어 위치 유지
      this.ghost.x = api.player.x;
      this.ghost.y = api.player.y;
    }
  }

  override onDestroy(_api: GameSceneAPI): void {
    this.ghost?.destroy();
    this.pendingAttacks.forEach(({ timer, ghost }) => {
      timer.remove();
      if (ghost.active) ghost.destroy();
    });
    this.pendingAttacks = [];
  }

  private collectSpecialWithGhost(api: GameSceneAPI, count: number): void {
    if (!this.ghost) return;

    const allSpecial = [
      ...api.goldPoops.getChildren(),
      ...api.diamondPoops.getChildren(),
      ...api.topazPoops.getChildren(),
      ...api.rainbowPoops.getChildren(),
    ].filter(p => (p as Phaser.GameObjects.GameObject).active) as Phaser.Physics.Arcade.Sprite[];

    if (allSpecial.length === 0) return;

    const targets = allSpecial.slice(0, count);

    targets.forEach(target => {
      const attackGhost = api.scene.add
        .image(target.x, target.y, 'glitch_front')
        .setDisplaySize(60, 80)
        .setAlpha(1.0)
        .setDepth(6);

      // entry를 먼저 생성한 뒤 timer 참조를 채움 (자기 참조용)
      const entry: { timer: Phaser.Time.TimerEvent; ghost: Phaser.GameObjects.Image } = {
        timer: null as unknown as Phaser.Time.TimerEvent,
        ghost: attackGhost,
      };
      entry.timer = api.scene.time.delayedCall(1000, () => {
        // 완료된 엔트리는 즉시 배열에서 제거 (장기 누수 방지)
        const idx = this.pendingAttacks.indexOf(entry);
        if (idx !== -1) this.pendingAttacks.splice(idx, 1);
        if (attackGhost.active) attackGhost.destroy();
        if (!target.active) return;
        if (api.goldPoops.contains(target))         api.collectGoldPoop(target);
        else if (api.diamondPoops.contains(target)) api.collectDiamondPoop(target);
        else if (api.topazPoops.contains(target))   api.collectTopazPoop(target);
        else if (api.rainbowPoops.contains(target)) api.collectRainbowPoop(target);
      });
      this.pendingAttacks.push(entry);
    });
  }
}

/**
 * 캐릭터 능력 수치 설정 (단일 진실 공급원)
 *
 * PARAMS  — 능력 클래스에서 사용하는 숫자/비율 값
 * DESC    — PARAMS로 자동 생성되는 설명 문자열 (character.ts에서 import)
 *
 * 수치를 바꾸면 게임 로직과 캐릭터 정보 패널이 동시에 갱신됩니다.
 */

// ── 루트 (Hacker / SR) ────────────────────────────────────────────────
export const HACKER_PARAMS = {
  deleteInterval: 100,      // 터미널 삭제 점수 간격
  deleteCount: 7,           // 삭제하는 똥 개수
  specialPoopSlowdown: 40,  // 특수 똥 낙하 속도 감소 (px/s)
} as const;

export const HACKER_DESC = {
  basicEffect: '금똥·다이아똥 낙하 속도 감소',
  specialAbility: `${HACKER_PARAMS.deleteInterval}점마다 일반 똥 ${HACKER_PARAMS.deleteCount}개 터미널 삭제`,
} as const;

// ── 광부 (Miner / SR) ─────────────────────────────────────────────────
export const MINER_PARAMS = {
  specialBonus: 5,         // 특수 똥 수집 시 추가 점수
  rainbowInterval: 350,     // 무지개똥 생성 점수 간격
} as const;

export const MINER_DESC = {
  basicEffect: `특수 똥 수집 시 +${MINER_PARAMS.specialBonus}점 추가`,
  specialAbility: `${MINER_PARAMS.rainbowInterval}점마다 무지개똥 생성`,
} as const;

// ── 매화 (Maehwa / SR) ────────────────────────────────────────────────
export const MAEHWA_PARAMS = {
  speedBonus: 50,           // 이동 속도 보너스 (px/s)
  slashInterval: 100,       // 칼 베기 점수 간격
  slashCount: 3,            // 한 번에 베는 똥 개수
  awake2SpecialBonus: 5,    // ★2+ 특수 똥 수집 추가 점수
} as const;

export const MAEHWA_DESC = {
  basicEffect: `이동 속도 +${MAEHWA_PARAMS.speedBonus}px/s`,
  specialAbility: `${MAEHWA_PARAMS.slashInterval}점마다 위쪽 똥 ${MAEHWA_PARAMS.slashCount}개 칼로 제거`,
} as const;

// ── 아카이브 (Archieve / SR) ──────────────────────────────────────────
export const ARCHIEVE_PARAMS = {
  scoreMultiplierExtra: 0.10, // 점수 배율 추가분 (base의 10% → 1.1배)
  bonusInterval: 200,         // 보너스 점수 간격
  bonusScore: 20,             // 보너스 점수
} as const;

export const ARCHIEVE_DESC = {
  basicEffect: `점수 획득 속도 ${1 + ARCHIEVE_PARAMS.scoreMultiplierExtra}배`,
  specialAbility: `${ARCHIEVE_PARAMS.bonusInterval}점마다 +${ARCHIEVE_PARAMS.bonusScore}점 보너스`,
} as const;

// ── 글리치 (Glitch / SR) ──────────────────────────────────────────────
export const GLITCH_PARAMS = {
  collectInterval: 200,     // 분신 소환 점수 간격
  collectCount: 1,          // 분신이 한 번에 수집하는 특수 똥 개수
} as const;

export const GLITCH_DESC = {
  basicEffect: '잔상 분신이 특수 똥 수집',
  specialAbility: `${GLITCH_PARAMS.collectInterval}점마다 특수 똥 위치에 분신 소환`,
} as const;

// ── 노이즈 (Noise / SR) ───────────────────────────────────────────────
export const NOISE_PARAMS = {
  spawnShortening: 0.25,    // 특수 똥 생성 주기 단축 비율 (25%)
  reductionInterval: 200,   // 소환 감소 점수 간격
  reductionAmount: 2,       // 소환 감소 개수
  goldInterval: 30,         // 금똥 생성 간격 (기본 40의 75%)
  diamondInterval: 75,      // 다이아똥 생성 간격 (기본 100의 75%)
  topazInterval: 135,       // 토파즈똥 생성 간격 (기본 180의 75%)
} as const;

export const NOISE_DESC = {
  basicEffect: `특수 똥 생성 주기 ${NOISE_PARAMS.spawnShortening * 100}% 단축`,
  specialAbility: `${NOISE_PARAMS.reductionInterval}점마다 다음 소환 ${NOISE_PARAMS.reductionAmount}개 감소`,
} as const;

// ── 센티넬 (Sentinel / UR) ────────────────────────────────────────────
export const SENTINEL_PARAMS = {
  startShields: 2,          // 시작 보호막 개수
