   429→  private showNextReveal() {
   430→    if (this.revealIndex >= this.pullResults.length) {
   431→      this.showSummary();
   432→      return;
   433→    }
   434→
   435→    const pulled = this.pullResults[this.revealIndex];
   436→    const def = getCharacterDef(pulled.id);
   437→
   438→    const { width, height } = this.cameras.main;
   439→    this.clearUI();
   440→
   441→    const vidKey = `vid_${pulled.id}`;
   442→    if (this.cache.video.exists(vidKey)) {
   443→      const vid = this.add.video(width / 2, height / 2, vidKey);
   444→      vid.play(false);
   445→      this.fitVideoToCanvas(vid, width, height);
   446→
   447→      let proceeded = false;
   448→      const proceed = () => {
   449→        if (proceeded) return;
   450→        proceeded = true;
   451→        this.input.off('pointerdown', proceed);
   452→        if (vid.active) vid.destroy();
   453→        this.showRevealCard(pulled, def);
   454→      };
   455→
   456→      this.addSkipButton(() => {
   457→        if (proceeded) return;
   458→        proceeded = true;
   459→        this.input.off('pointerdown', proceed);
   460→        if (vid.active) vid.destroy();
   461→        // 10연차: 영상 스킵 시 남은 리빌 전체 건너뛰고 결과 화면으로
   462→        if (this.pullResults.length > 1) {
   463→          this.showSummary();
   464→        } else {
   465→          this.showRevealCard(pulled, def);
   466→        }
   467→      });
   468→      vid.on('complete', proceed);
   469→      this.time.delayedCall(10000, proceed); // failsafe
   470→      this.input.once('pointerdown', proceed); // 탭으로 스킵
   471→    } else {
   472→      this.showRevealCard(pulled, def);
   473→    }
   474→  }
