   476→  private showRevealCard(pulled: PulledCharacter, def: CharacterDef) {
   477→    const gColor = GRADE_COLORS[pulled.grade] ?? 0xffffff;
   478→
   479→    // ── 배경: 사이버 우주 이미지 + 등급 컬러 헤이즈 ──
   480→    if (this.textures.exists('gacha_background')) {
   481→      const bg = this.add.image(200, 300, 'gacha_background');
   482→      bg.setDisplaySize(400, 600);
   483→    } else {
   484→      this.add.rectangle(200, 300, 400, 600, 0x050510);
   485→    }
   486→    // 어두운 오버레이 (가독성 확보)
   487→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.5);
   488→    // 등급 컬러 헤이즈 (중앙 중심 방사)
   489→    this.add.circle(200, 260, 200, gColor, 0.08);
   490→    this.add.circle(200, 260, 120, gColor, 0.06);
   491→
   492→    // 배경 글로우 (캐릭터 뒤 빛)
   493→    const glow = this.add.circle(200, 255, 150, gColor, 0.0).setAlpha(0);
   494→    this.tweens.add({
   495→      targets: glow, alpha: 1,
   496→      scaleX: { from: 0.3, to: 1.3 }, scaleY: { from: 0.3, to: 1.3 },
   497→      duration: 600, ease: 'Back.easeOut',
   498→    });
   499→
   500→    // 캐릭터 이미지
   501→    const img = this.add.image(200, 240, def.imageKey).setAlpha(0);
   502→    img.setDisplaySize(130, 205);
   503→    this.tweens.add({
   504→      targets: img, alpha: 1, y: { from: 268, to: 240 },
   505→      duration: 500, ease: 'Back.easeOut', delay: 150,
   506→    });
   507→
   508→    // 등급 라벨
   509→    const gradeText = this.add.text(200, 388, pulled.grade, {
   510→      fontSize: '18px', color: def.gradeColor, fontStyle: 'bold',
   511→      stroke: '#000', strokeThickness: 4, fontFamily: 'monospace',
   512→    }).setOrigin(0.5).setAlpha(0);
   513→    this.tweens.add({ targets: gradeText, alpha: 1, duration: 300, delay: 400 });
   514→
   515→    // 캐릭터 이름
   516→    const nameText = this.add.text(200, 424, def.name, {
   517→      fontSize: '34px', color: '#ffffff', fontStyle: 'bold',
   518→      stroke: '#000000', strokeThickness: 6,
   519→    }).setOrigin(0.5).setAlpha(0);
   520→    this.tweens.add({
   521→      targets: nameText, alpha: 1, y: { from: 442, to: 424 },
   522→      duration: 400, ease: 'Back.easeOut', delay: 500,
   523→    });
   524→
   525→    // NEW! 배지
   526→    if (pulled.isNew) {
   527→      const badge = this.add.text(325, 145, ' NEW! ', {
   528→        fontSize: '15px', color: '#ffff00', fontStyle: 'bold',
   529→        backgroundColor: '#cc0000', stroke: '#000', strokeThickness: 2,
   530→      }).setOrigin(0.5).setAlpha(0).setScale(0);
   531→      this.tweens.add({
   532→        targets: badge, alpha: 1, scaleX: 1, scaleY: 1,
   533→        duration: 300, ease: 'Back.easeOut', delay: 650,
   534→      });
   535→    }
   536→
   537→    // 탭 안내
   538→    const isLast = this.revealIndex >= this.pullResults.length - 1;
   539→    const hint = isLast
   540→      ? 'TAP → RESULTS'
   541→      : `TAP → NEXT  (${this.revealIndex + 1}/${this.pullResults.length})`;
   542→    const tapHint = this.add.text(200, 562, hint, {
   543→      fontSize: '13px', color: '#555555', fontFamily: 'monospace',
   544→    }).setOrigin(0.5);
   545→    this.tweens.add({
   546→      targets: tapHint, alpha: { from: 0.3, to: 1 }, duration: 600, yoyo: true, repeat: -1,
   547→    });
   548→
   549→    // 10연차: 결과 화면으로 바로 건너뛰기 (영상 유무와 무관하게 항상 표시)
   550→    if (this.pullResults.length > 1) {
   551→      this.addSkipButton(() => {
   552→        this.tweens.killAll();
   553→        this.time.removeAllEvents();
   554→        this.input.off('pointerdown');
   555→        this.showSummary();
   556→      });
   557→    }
   558→
   559→    // 탭 진행 (700ms 디바운스)
   560→    this.time.delayedCall(700, () => {
   561→      if (!this.scene.isActive()) return;
   562→
   563→      let advanced = false;
   564→      const advance = () => {
   565→        if (advanced) return;
   566→        advanced = true;
   567→        this.input.off('pointerdown', advance);
   568→        this.tweens.killAll();
   569→        this.time.removeAllEvents();
   570→        this.revealIndex++;
   571→        this.showNextReveal();
   572→      };
   573→
   574→      this.input.on('pointerdown', advance);
   575→
   576→      // 10뽑기는 3.5초 자동 진행
   577→      if (this.pullResults.length > 1) {
   578→        this.time.delayedCall(3500, () => {
   579→          if (this.scene.isActive()) advance();
   580→        });
   581→      }
   582→    });
