   699→      Promise.resolve()
   700→    );
   701→  }
   702→
   703→  private typeLine(text: string, charDelay = 40, color = '#00ff41'): Promise<void> {
   704→    return new Promise(resolve => {
   705→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   706→
   707→      // 최대 6줄 유지 (스크롤 효과)
   708→      if (this.terminalTexts.length >= 6) {
   709→        this.terminalTexts.shift()?.destroy();
   710→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   711→      }
   712→
   713→      const y = 276 + this.terminalTexts.length * 22;
   714→      const t = this.add.text(24, y, '', {
   715→        fontSize: '13px', color, fontFamily: 'monospace',
   716→      });
   717→      this.terminalTexts.push(t);
   718→
   719→      let i = 0;
   720→      const ev = this.time.addEvent({
   721→        delay: charDelay,
   722→        repeat: text.length,
   723→        callback: () => {
   724→          if (!this.scene.isActive() || this.skipTerminal) { ev.destroy(); resolve(); return; }
   725→          t.setText(text.substring(0, i + 1));
   726→          i++;
   727→          if (i > text.length) { ev.destroy(); resolve(); }
   728→        },
   729→      });
   730→    });
   731→  }
   732→
   733→  private progressBar(duration: number, color = '#00ff41'): Promise<void> {
   734→    return new Promise(resolve => {
   735→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   736→
   737→      if (this.terminalTexts.length >= 6) {
   738→        this.terminalTexts.shift()?.destroy();
   739→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   740→      }
   741→
   742→      const y = 276 + this.terminalTexts.length * 22;
   743→      const bar = this.add.text(24, y, '> [          ]  0%', {
   744→        fontSize: '13px', color, fontFamily: 'monospace',
   745→      });
   746→      this.terminalTexts.push(bar);
   747→
   748→      let step = 0;
   749→      const steps = 10;
   750→      const ev = this.time.addEvent({
   751→        delay: duration / steps,
   752→        repeat: steps - 1,
   753→        callback: () => {
   754→          step++;
   755→          bar.setText(`> [${'█'.repeat(step)}${' '.repeat(steps - step)}] ${step * 10}%`);
   756→          if (this.skipTerminal || step >= steps) { ev.destroy(); resolve(); }
   757→        },
   758→      });
   759→    });
   760→  }
   761→
   762→  private sleep(ms: number): Promise<void> {
   763→    return new Promise(resolve => {
   764→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   765→      this.time.delayedCall(ms, resolve);
   766→    });
   767→  }
