   442→  /**
   443→   * 로드 완료된 비디오를 패널에 추가하고 인터랙션을 연결.
   444→   * 패널 z-order: blocker(0) → illust(1) → grad(2) → …
   445→   * videoObj는 illust 바로 위, grad 아래인 index=2에 삽입.
   446→   */
   447→  private setupDetailVideo(def: CharacterDef, illust: Phaser.GameObjects.Image, panel: Phaser.GameObjects.Container): void {
   448→    if (!panel.active || !def.videoKey) return;
   449→
   450→    const videoObj = this.add.video(200, 300, def.videoKey).setDisplaySize(400, 600).setVisible(false);
   451→    // gradient(index 2) 아래에 삽입 → 버튼·텍스트 뒤에 렌더되지 않도록
   452→    panel.addAt(videoObj, 2);
   453→    this.detailVideo = videoObj;
   454→
   455→    // 일러스트 탭 → 비디오 재생
   456→    const startVideo = () => {
   457→      if (!illust.active || !videoObj.active) return;
   458→      videoObj.setVisible(true);
   459→      videoObj.play(false);
   460→      this.fitVideoToPanel(videoObj);
   461→      // 실제 재생 시작 후 일러스트 숨김 (첫 프레임 갭 방지)
   462→      videoObj.once('play', () => {
   463→        if (illust.active) illust.setVisible(false);
   464→      });
   465→    };
   466→    illust.setInteractive({ useHandCursor: true });
   467→    illust.on('pointerup', startVideo);
   468→
   469→    // 비디오 탭 또는 재생 완료 → 일러스트로 복귀
   470→    const stopVideo = () => {
   471→      videoObj.stop();
   472→      videoObj.setVisible(false);
   473→      illust.setVisible(true);
   474→    };
   475→    videoObj.setInteractive({ useHandCursor: true });
   476→    videoObj.on('pointerup', stopVideo);
   477→    videoObj.on('complete', stopVideo);
   478→  }
   479→
   480→  /** GachaScene.fitVideoToCanvas와 동일 — aspect ratio 유지하며 400×600 캔버스에 cover */
   481→  private fitVideoToPanel(vid: Phaser.GameObjects.Video): void {
   482→    const W = 400, H = 600;
   483→    vid.setDisplaySize(W, H);
   484→
   485→    const applyContain = () => {
   486→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   487→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
   488→      const nw = el?.videoWidth  || 0;
   489→      const nh = el?.videoHeight || 0;
   490→      if (nw > 0 && nh > 0) {
   491→        const scale = Math.max(W / nw, H / nh);
   492→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
   493→      }
   494→    };
   495→
   496→    vid.once('play', applyContain);
   497→    this.fitVideoTimers.push(this.time.delayedCall(100, applyContain));
   498→    this.fitVideoTimers.push(this.time.delayedCall(500, applyContain));
   499→  }
   500→
   501→  private hideCharacterDetail(): void {
   502→    // fitVideoToPanel의 pending 타이머 취소
   503→    for (const t of this.fitVideoTimers) t.remove();
   504→    this.fitVideoTimers = [];
   505→
   506→    // 비디오 명시 정지, HTMLVideoElement src 완전 해제, VideoCache 제거
   507→    if (this.detailVideo) {
   508→      this.detailVideo.stop();
   509→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   510→      const el: HTMLVideoElement | null = (this.detailVideo as any).video ?? null;
   511→      if (el) { el.pause(); el.removeAttribute('src'); el.load(); } // W3C 표준 미디어 버퍼 해제
   512→      this.detailVideo = null;
   513→    }
   514→    // Phaser VideoCache에서도 제거 → 다음 열기 시 깨진 캐시 엔트리 방지
   515→    if (this.detailVideoKey) {
   516→      this.cache.video.remove(this.detailVideoKey);
   517→      this.detailVideoKey = null;
   518→    }
   519→
   520→    this.hideInfoPanel();
   521→    this.detailPanel?.destroy();
   522→    this.detailPanel = null;
   523→  }
