   225→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
   226→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
   227→    this.cardsContainer.add(cardBg);
   228→
   229→    // 선택 하이라이트
   230→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
   231→    highlight.setStrokeStyle(3, 0xffffff);
   232→    highlight.setVisible(isSelected);
   233→    this.cardHighlights.set(char.id, highlight);
   234→    this.cardsContainer.add(highlight);
   235→
   236→    // 캐릭터 이미지
   237→    const img = this.add.image(x, y - 12, char.imageKey);
   238→    img.setDisplaySize(58, 85);
   239→    this.cardsContainer.add(img);
   240→
   241→    if (!isOwned) {
   242→      img.setTint(0x000000);
