   244→      const lock = this.add.text(x, y - 12, '🔒', { fontSize: '22px' }).setOrigin(0.5);
   245→      this.cardsContainer.add(lock);
   246→    }
   247→
   248→    // 등급 배지
   249→    const badge = this.add.text(x + CARD_W / 2 - 2, y - CARD_H / 2 + 2, char.grade, {
   250→      fontSize: '9px',
   251→      color: char.gradeColor,
   252→      fontStyle: 'bold',
   253→      backgroundColor: '#000000cc',
   254→      padding: { x: 3, y: 1 },
   255→    }).setOrigin(1, 0);
   256→    this.cardsContainer.add(badge);
   257→
   258→    // 각성 코어 (등급외 제외, 보유 캐릭터만) — 공유 coresGfx에 직접 그림
   259→    if (isOwned && char.grade !== '등급외') {
   260→      const dupCount   = getDuplicateCount(char.id);
   261→      const awakeLevel = getAwakeningLevel(char.grade, dupCount);
   262→      const coreY      = y + CARD_H / 2 - CORE_Y_OFFSET;
   263→
   264→      for (let i = 0; i < CORE_COUNT; i++) {
   265→        const cx = x + (i - 2) * CORE_GAP;
