   270→          this.coresGfx.fillStyle(gradeColorInt, 1);
   271→          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
   272→          this.coresGfx.fillStyle(0xffffff, 0.55);
   273→          this.coresGfx.fillCircle(cx - 1, coreY - 1, CORE_HIGHLIGHT_R);
