   277→          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
   278→          this.coresGfx.lineStyle(1, gradeColorInt, 0.35);
   279→          this.coresGfx.strokeCircle(cx, coreY, CORE_INNER_RADIUS);
