   480→  /** GachaScene.fitVideoToCanvas와 동일 — aspect ratio 유지하며 400×600 캔버스에 cover */
   481→  private fitVideoToPanel(vid: Phaser.GameObjects.Video): void {
   482→    const W = 400, H = 600;
   483→    vid.setDisplaySize(W, H);
   484→
   485→    const applyContain = () => {
   486→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   487→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
   488→      const nw = el?.videoWidth  || 0;
   489→      const nh = el?.videoHeight || 0;
   490→      if (nw > 0 && nh > 0) {
   491→        const scale = Math.max(W / nw, H / nh);
   492→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
   493→      }
   494→    };
   495→
   496→    vid.once('play', applyContain);
   497→    this.fitVideoTimers.push(this.time.delayedCall(100, applyContain));
   498→    this.fitVideoTimers.push(this.time.delayedCall(500, applyContain));
   499→  }
