    15→const CARD_W = 100;
    16→const CARD_H = 120;
    17→const GAP_X = 15;
    18→const GAP_Y = 10;
    19→const GRID_LEFT = (400 - (COLS * CARD_W + (COLS - 1) * GAP_X)) / 2; // 35px
