    86→
    87→    // 동기화 전 각성 수치 스냅샷 (동기화 후 변화 감지용)
    88→    this._preSyncDupCounts = new Map(
    89→      CHARACTERS
    90→        .filter(c => this.ownedIds.includes(c.id) && c.grade !== '등급외')
    91→        .map(c => [c.id, getDuplicateCount(c.id)])
    92→    );
    93→
    94→    // 서버 DB와 동기화 — 소유 목록 or 각성 수치가 바뀐 경우 씬 재시작해서 카드 갱신
    95→    syncOwnedCharacters().then(synced => {
    96→      if (!this.scene.isActive()) return;
    97→      const ownedChanged = synced.length !== this.ownedIds.length ||
    98→        synced.some(id => !this.ownedIds.includes(id));
    99→      // 각성 수치 변화 여부: 동기화 후 localStorage의 duplicate_count가 달라졌으면 재시작
   100→      const awakeChanged = CHARACTERS.some(c =>
