   105→    }).catch(() => { /* 네트워크 오류 시 로컬 상태 유지 */ });
   106→
   107→    const selectedDef = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   108→
   109→    // ── 배경: 선택된 캐릭터 일러스트 ───────────────────────────────────
   110→    this.bgImage = this.add.image(200, 300, selectedDef.illustKey);
   111→    this.bgImage.setDisplaySize(400, 600);
   112→
   113→    // ── 헤더 (고정) ─────────────────────────────────────────────────────
   114→    this.add.text(200, 40, '캐릭터 선택', {
   115→      fontSize: '26px',
   116→      color: '#ffffff',
   117→      fontStyle: 'bold',
   118→      stroke: '#000',
   119→      strokeThickness: 4,
   120→    }).setOrigin(0.5);
   121→
   122→    this.headerNameText = this.add.text(200, 80, `현재: ${selectedDef.name}`, {
   123→      fontSize: '16px',
   124→      color: selectedDef.gradeColor,
   125→      stroke: '#000',
   126→      strokeThickness: 3,
   127→    }).setOrigin(0.5);
   128→
   129→    this.add.text(200, 108, '수집한 캐릭터를 선택하세요', {
   130→      fontSize: '13px',
   131→      color: '#888888',
   132→    }).setOrigin(0.5);
   133→
   134→    // ── 스크롤 가능한 카드 컨테이너 ─────────────────────────────────────
   135→    this.cardsContainer = this.add.container(0, 0);
   136→
   137→    // 각성 코어 전용 단일 Graphics (카드당 1개 생성하던 것을 통합)
   138→    this.coresGfx = this.add.graphics();
   139→    CHARACTERS.forEach((char, index) => {
   140→      const col = index % COLS;
   141→      const row = Math.floor(index / COLS);
   142→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
   143→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
   144→      this.createCharacterCard(char, x, y);
   145→    });
   146→    this.cardsContainer.add(this.coresGfx);
   147→
   148→    // 스크롤 최대 범위 계산
   149→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   150→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   151→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   152→
   153→    // 카드 영역 마스크 (스크롤 영역 밖 숨김)
   154→    // this.make: display list에 추가되지 않으므로 shutdown 시 직접 정리 필요
   155→    this.maskGfx = this.make.graphics({ x: 0, y: 0 });
   156→    this.maskGfx.fillStyle(0xffffff);
   157→    this.maskGfx.fillRect(0, SCROLL_TOP, 400, SCROLL_BOTTOM - SCROLL_TOP);
   158→    this.cardsContainer.setMask(this.maskGfx.createGeometryMask());
   159→
   160→    // ── 드래그 스크롤 입력 ───────────────────────────────────────────────
   161→    this.input.on('pointerdown', (p: Phaser.Input.Pointer) => {
   162→      this.hasPointerDownInScene = true;
   163→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   164→      if (p.y < SCROLL_TOP || p.y > SCROLL_BOTTOM) return;
