   196→      'wheel',
   197→      (_p: Phaser.Input.Pointer, _go: unknown[], _dx: number, deltaY: number) => {
   198→        if (this.detailPanel) return; // 상세 패널 열려있으면 휠 스크롤 무시
   199→        this.scrollOffset = Phaser.Math.Clamp(
