   201→          0,
   202→          this.maxScrollOffset,
   203→        );
   204→        this.cardsContainer.setY(-this.scrollOffset);
   205→      },
   206→    );
   207→
   208→    // ── 고정 UI ─────────────────────────────────────────────────────────
   209→    this.createBackButton();
   210→
   211→    // maskGfx는 display list 외부에 있으므로 씬 종료 시 직접 정리
