   218→
   219→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
   220→    const isOwned = this.ownedIds.includes(char.id);
   221→    const isSelected = this.selectedId === char.id;
   222→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
   223→
   224→    // 카드 배경
   225→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
   226→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
   227→    this.cardsContainer.add(cardBg);
   228→
   229→    // 선택 하이라이트
   230→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
   231→    highlight.setStrokeStyle(3, 0xffffff);
   232→    highlight.setVisible(isSelected);
   233→    this.cardHighlights.set(char.id, highlight);
   234→    this.cardsContainer.add(highlight);
   235→
   236→    // 캐릭터 이미지
   237→    const img = this.add.image(x, y - 12, char.imageKey);
   238→    img.setDisplaySize(58, 85);
   239→    this.cardsContainer.add(img);
   240→
   241→    if (!isOwned) {
   242→      img.setTint(0x000000);
   243→      img.setAlpha(0.6);
   244→      const lock = this.add.text(x, y - 12, '🔒', { fontSize: '22px' }).setOrigin(0.5);
   245→      this.cardsContainer.add(lock);
   246→    }
   247→
   248→    // 등급 배지
   249→    const badge = this.add.text(x + CARD_W / 2 - 2, y - CARD_H / 2 + 2, char.grade, {
   250→      fontSize: '9px',
   251→      color: char.gradeColor,
   252→      fontStyle: 'bold',
   253→      backgroundColor: '#000000cc',
   254→      padding: { x: 3, y: 1 },
   255→    }).setOrigin(1, 0);
   256→    this.cardsContainer.add(badge);
   257→
   258→    // 각성 코어 (등급외 제외, 보유 캐릭터만) — 공유 coresGfx에 직접 그림
   259→    if (isOwned && char.grade !== '등급외') {
   260→      const dupCount   = getDuplicateCount(char.id);
   261→      const awakeLevel = getAwakeningLevel(char.grade, dupCount);
   262→      const coreY      = y + CARD_H / 2 - CORE_Y_OFFSET;
   263→
   264→      for (let i = 0; i < CORE_COUNT; i++) {
