   445→   * videoObj는 illust 바로 위, grad 아래인 index=2에 삽입.
   446→   */
   447→  private setupDetailVideo(def: CharacterDef, illust: Phaser.GameObjects.Image, panel: Phaser.GameObjects.Container): void {
   448→    if (!panel.active || !def.videoKey) return;
   449→
   450→    const videoObj = this.add.video(200, 300, def.videoKey).setDisplaySize(400, 600).setVisible(false);
   451→    // gradient(index 2) 아래에 삽입 → 버튼·텍스트 뒤에 렌더되지 않도록
   452→    panel.addAt(videoObj, 2);
   453→    this.detailVideo = videoObj;
   454→
   455→    // 일러스트 탭 → 비디오 재생
   456→    const startVideo = () => {
   457→      if (!illust.active || !videoObj.active) return;
   458→      videoObj.setVisible(true);
   459→      videoObj.play(false);
   460→      this.fitVideoToPanel(videoObj);
   461→      // 실제 재생 시작 후 일러스트 숨김 (첫 프레임 갭 방지)
   462→      videoObj.once('play', () => {
   463→        if (illust.active) illust.setVisible(false);
   464→      });
   465→    };
   466→    illust.setInteractive({ useHandCursor: true });
   467→    illust.on('pointerup', startVideo);
   468→
   469→    // 비디오 탭 또는 재생 완료 → 일러스트로 복귀
   470→    const stopVideo = () => {
   471→      videoObj.stop();
   472→      videoObj.setVisible(false);
   473→      illust.setVisible(true);
   474→    };
   475→    videoObj.setInteractive({ useHandCursor: true });
   476→    videoObj.on('pointerup', stopVideo);
   477→    videoObj.on('complete', stopVideo);
   478→  }
