   505→
   506→    // 비디오 명시 정지, HTMLVideoElement src 완전 해제, VideoCache 제거
   507→    if (this.detailVideo) {
   508→      this.detailVideo.stop();
   509→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   510→      const el: HTMLVideoElement | null = (this.detailVideo as any).video ?? null;
   511→      if (el) { el.pause(); el.removeAttribute('src'); el.load(); } // W3C 표준 미디어 버퍼 해제
   512→      this.detailVideo = null;
   513→    }
   514→    // Phaser VideoCache에서도 제거 → 다음 열기 시 깨진 캐시 엔트리 방지
   515→    if (this.detailVideoKey) {
   516→      this.cache.video.remove(this.detailVideoKey);
   517→      this.detailVideoKey = null;
   518→    }
   519→
   520→    this.hideInfoPanel();
   521→    this.detailPanel?.destroy();
   522→    this.detailPanel = null;
   523→  }
