   323→    if (isUR) {
   324→      const red = '#ff3333';
   325→      // 초반: 정상처럼 초록으로 시작
   326→      await this.typeLines([
   327→        `> EXECUTE entity_summon(n=${count})`,
   328→        '> Establishing connection...',
   329→      ], 18);
   330→      await this.progressBar(400);
   331→      await this.typeLines([
   332→        '> CONN: OK  [sec-layer bypassed]',
