   334→      ], 16);
   335→      await this.progressBar(350);
   336→      // 이상 감지 시점부터 빨간색으로 전환
   337→      await this.typeLines([
   338→        '> [WARN] Anomaly detected',
   339→        '> [ERR]  Containment failure',
   340→      ], 18, red);
   341→      await this.progressBar(450, red);
   342→      await this.typeLines([
