   351→      ], 18);
   352→      await this.progressBar(400);
   353→      await this.typeLines([
   354→        '> CONN: OK  [sec-layer bypassed]',
   355→        '> Scanning entity pool...',
   356→      ], 16);
   357→      await this.progressBar(350);
   358→      await this.typeLines([
