   589→  private showSummary() {
   590→    this.clearUI();
   591→    if (this.textures.exists('gacha_background')) {
   592→      this.add.image(200, 300, 'gacha_background').setDisplaySize(400, 600);
   593→    } else {
   594→      this.add.rectangle(200, 300, 400, 600, 0x060612);
   595→    }
   596→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.55);
   597→
   598→    this.add.text(200, 38, '[ EXTRACTION COMPLETE ]', {
   599→      fontSize: '17px', color: '#00ff41', fontStyle: 'bold', fontFamily: 'monospace',
   600→    }).setOrigin(0.5);
   601→
   602→    // 결과 카드 그리드
   603→    const total = this.pullResults.length;
   604→    const cols = Math.min(total, 5);
   605→    const cardW = 64, cardH = 84, gapX = 8, gapY = 12;
   606→    const totalW = cols * cardW + (cols - 1) * gapX;
   607→    const startX = (400 - totalW) / 2 + cardW / 2;
   608→    const startY = total > 5 ? 130 : 175;
   609→
   610→    this.pullResults.forEach((pulled, i) => {
   611→      const def = getCharacterDef(pulled.id);
   612→      const col = i % 5;
   613→      const row = Math.floor(i / 5);
   614→      const x = startX + col * (cardW + gapX);
   615→      const y = startY + row * (cardH + gapY);
   616→      const gColorInt = parseInt(def.gradeColor.replace('#', ''), 16);
   617→
   618→      const bg  = this.add.rectangle(x, y, cardW, cardH, 0x111122).setStrokeStyle(1, gColorInt).setAlpha(0);
   619→      const img = this.add.image(x, y - 8, def.imageKey).setDisplaySize(cardW - 19, cardH - 22).setAlpha(0);
   620→      const nm  = this.add.text(x, y + cardH / 2 - 10, def.name, { fontSize: '9px', color: '#cccccc' }).setOrigin(0.5).setAlpha(0);
   621→
   622→      if (pulled.isNew) {
   623→        this.add.text(x + cardW / 2, y - cardH / 2 + 2, 'NEW', {
   624→          fontSize: '8px', color: '#ffff00', backgroundColor: '#aa0000', padding: { x: 2, y: 1 },
   625→        }).setOrigin(1, 0).setAlpha(0);
   626→      }
   627→
   628→      this.tweens.add({ targets: [bg, img, nm], alpha: 1, duration: 200, delay: i * 60 });
   629→    });
   630→
   631→    // 잔여 SKOR
   632→    const skorY = total > 5 ? 350 : 340;
   633→    this.add.text(200, skorY, `잔여 SKOR: ${Math.floor(this.remainingSkor)}`, {
   634→      fontSize: '14px', color: '#00ff41', fontFamily: 'monospace',
   635→    }).setOrigin(0.5);
   636→
   637→    // 한 번 더 / 메인으로 버튼
   638→    const againBtn = this.add.rectangle(200, 445, 260, 52, 0x080818)
   639→      .setStrokeStyle(1, 0x00ff41).setInteractive({ useHandCursor: true });
   640→    this.add.text(200, 445, '한 번 더', {
   641→      fontSize: '19px', color: '#00ff41', fontStyle: 'bold', fontFamily: 'monospace',
   642→    }).setOrigin(0.5);
   643→    againBtn.on('pointerover', () => againBtn.setFillStyle(0x081808));
   644→    againBtn.on('pointerout',  () => againBtn.setFillStyle(0x080818));
   645→    againBtn.on('pointerdown', () => this.buildLobby());
   646→
   647→    const mainBtn = this.add.rectangle(200, 525, 260, 52, 0x1a1a1a)
   648→      .setStrokeStyle(1, 0x444444).setInteractive({ useHandCursor: true });
   649→    this.add.text(200, 525, '메인으로', {
   650→      fontSize: '19px', color: '#888888', fontStyle: 'bold', fontFamily: 'monospace',
   651→    }).setOrigin(0.5);
   652→    mainBtn.on('pointerover', () => mainBtn.setFillStyle(0x282828));
   653→    mainBtn.on('pointerout',  () => mainBtn.setFillStyle(0x1a1a1a));
   654→    mainBtn.on('pointerdown', () => this.scene.start('ModeSelectScene'));
   655→  }
