 * 패널 z-order: blocker(0) → illust(1) → grad(2) → …
 * videoObj는 illust 바로 위, grad 아래인 index=2에 삽입.
 */
private setupDetailVideo(def: CharacterDef, illust: Phaser.GameObjects.Image, panel: Phaser.GameObjects.Container): void {
  if (!panel.active || !def.videoKey) return;

  const videoObj = this.add.video(200, 300, def.videoKey).setDisplaySize(400, 600).setVisible(false);
  // gradient(index 2) 아래에 삽입 → 버튼·텍스트 뒤에 렌더되지 않도록
  panel.addAt(videoObj, 2);
  this.detailVideo = videoObj;

  // 일러스트 탭 → 비디오 재생
  const startVideo = () => {
    if (!illust.active || !videoObj.active) return;
    videoObj.setVisible(true);
    videoObj.play(false);
    this.fitVideoToPanel(videoObj);
    // 실제 재생 시작 후 일러스트 숨김 (첫 프레임 갭 방지)
    videoObj.once('play', () => {
      if (illust.active) illust.setVisible(false);
    });
  };
  illust.setInteractive({ useHandCursor: true });
  illust.on('pointerup', startVideo);

  // 비디오 탭 또는 재생 완료 → 일러스트로 복귀
  const stopVideo = () => {
    videoObj.stop();
    videoObj.setVisible(false);
    illust.setVisible(true);
  };
  videoObj.setInteractive({ useHandCursor: true });
  videoObj.on('pointerup', stopVideo);
  videoObj.on('complete', stopVideo);
}

