import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// 보너스 아이템 점수 가중치 (클라이언트 GameScene과 동일하게 유지)
// gold:+20, diamond:+40, topaz:+80, rainbow:+90
function calcBonusScore(v: { goldCollected?: number; diamondCollected?: number; topazCollected?: number; rainbowCollected?: number } | undefined): number {
  if (!v) return 0;
  return (v.goldCollected ?? 0) * 20 +
         (v.diamondCollected ?? 0) * 40 +
         (v.topazCollected ?? 0) * 80 +
         (v.rainbowCollected ?? 0) * 90;
}

// 난이도별 물리적 최대 점수 (2시간 연속 플레이 기준)
const SCORE_CAPS: Record<string, number> = {
  easy: 10000,
  normal: 15000,
  hard: 20000,
  extreme: 30000,
  physical: 30000,
};

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { score, difficulty, userName, sessionId, verification, characterType } = await req.json();

    // 기본 입력 검증

