 * // 4.5초간 지속
 * // 일반 똥 2개 + 금똥/다이아똥 8개 생성
 * // 낙하 속도 1.2배 빠름
 */
export const FEVER_TIME_CONFIG: FeverTimeConfig = {
  firstTriggerScore: 300,
  repeatInterval: 1300,
  duration: 4500,
  normalPoopCount: 2,
  bonusPoopCount: 8,
  speedMultiplier: 1.2, // 피버 타임 중 1.5배 빠른 속도
  ui: {
    fontSize: '32px',
    color: '#ff9900', // 주황색
    position: { x: 200, y: 120 },
    depth: 150, // 다른 UI 요소 위에 표시
    stroke: '#000000',
    strokeThickness: 4
  }
};

